      if (saveFloor) {
        saved = await firstValueFrom(this.http.put<SettingsView>(`${url}/floor`, { floor, from: fromOf('floor') }, this.session.headers()));
        this.floorEdited = false;
      }
      if (saveTerms) {
        saved = await firstValueFrom(this.http.put<SettingsView>(`${url}/terms`, { terms, from: fromOf('terms') }, this.session.headers()));
        this.termsEdited = false;
      }
      for (const g of saveGradeTerms) {
        const gradeTerms = (this.gradeTerms()[g] ?? '').trim();
        saved = await firstValueFrom(
          this.http.put<SettingsView>(`${url}/terms/${g}`, { terms: gradeTerms, from: fromOf('terms-' + g) }, this.session.headers()),
        );
        this.gradeTermsEdited.delete(g);
      }
      if (saveLatePct) {
        saved = await firstValueFrom(this.http.put<SettingsView>(`${url}/late-pct`, { latePct, from: fromOf('late-pct') }, this.session.headers()));
        this.latePctEdited = false;
      }
      if (savePolicyDate) {
        saved = await firstValueFrom(
          this.http.put<SettingsView>(
            `${url}/policy-date`,
            { policyDate: policyDate === '' ? null : policyDate },
            this.session.headers(),
          ),
        );
        this.policyDateEdited = false;
      }
      if (savePeriodNumberingFrom) {
        saved = await firstValueFrom(
          this.http.put<SettingsView>(
            `${url}/period-numbering-from`,
            { periodNumberingFrom: periodNumberingFrom === '' ? null : periodNumberingFrom },
            this.session.headers(),
          ),
        );
        this.periodNumberingFromEdited = false;
      }
      if (saveCap) {
        saved = await firstValueFrom(
          this.http.put<SettingsView>(`${url}/cap`, { cap: cap === '' ? null : cap, from: fromOf('cap') }, this.session.headers()),
        );
        this.capEdited = false;
      }
      if (saved && this.session.sheet() === sheet) this.show(saved);
    } catch {
      this.settingsError.set('The settings could not be saved.');
    } finally {
      this.savingSettings = false;
    }
  }

  protected async saveRole(event: Event): Promise<void> {
    event.preventDefault();
    if (this.savingRole) return;
    this.roleError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const user = this.roleUser().trim();
    const role = this.roleName().trim();
    if (!user) {
      this.roleError.set('Type the user name to give a role.');
      return;
    }
    if (!ROLES.includes(role)) {
      this.roleError.set('A role is clerk or steward.');
      return;
    }
    this.savingRole = true;
    try {
      const saved = await firstValueFrom(
        this.http.put<RoleView>(`/api/sheets/${encodeURIComponent(sheet)}/roles`, { user, role }, this.session.headers()),
      );
      if (this.session.sheet() === sheet) {
        this.roleList.update((list) =>
          [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)),
        );
        this.roleUser.set('');
        this.roleName.set('');
      }
    } catch {
      this.roleError.set('The role could not be set.');
    } finally {
      this.savingRole = false;
    }
  }

  private async read(sheet: string): Promise<void> {
    const read = ++this.reads;
    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
    const [settings, roles] = await Promise.all([
      firstValueFrom(this.http.get<SettingsView>(`${url}/settings`, this.session.headers())),
      firstValueFrom(this.http.get<RoleView[]>(`${url}/roles`, this.session.headers())),
    ]).catch(() => [null, null]);
    // A later read wins over a slower earlier one.
    if (settings && roles && read === this.reads && this.session.sheet() === sheet) {
      this.show(settings);
      this.roleList.set(roles);
    }
  }

  /** Show the settings in force on the sheet's today, and put them back in the form with no from-dates. */
  private show(settings: SettingsView): void {
    this.session.dated.set(settings.dated);
    this.clerkLimit.set(settings.clerkLimit ?? '');
    this.floor.set(settings.floor);
    this.terms.set(String(settings.terms));
    const gradeTerms: Record<string, string> = {};
    for (const [g, t] of Object.entries(settings.gradeTerms)) gradeTerms[g] = String(t);
    this.gradeTerms.set(gradeTerms);
    this.latePct.set(settings.latePct);
    this.froms.set({});
    this.session.policyDate.set(settings.policyDate ?? '');
    this.policyDate.set(settings.policyDate ?? '');
    this.periodNumberingFromCurrent.set(settings.periodNumberingFrom ?? '');
    this.periodNumberingFrom.set(settings.periodNumberingFrom ?? '');
    this.cap.set(settings.cap ?? '');
    this.clerkLimitEdited = false;
    this.floorEdited = false;
    this.termsEdited = false;
    this.gradeTermsEdited.clear();
    this.latePctEdited = false;
    this.policyDateEdited = false;
    this.periodNumberingFromEdited = false;
    this.capEdited = false;
  }
}

import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** A dated setting's value (two decimals or whole days; null: none) from its from-date (yyyy-mm-dd). */
export interface DatedValue {
  from: string;
  value: string | null;
}

/** The sheet's starting values, in force before a key's first from-date: none for a key not listed. */
const STARTING: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

interface SheetView {
  id: string;
  today: string;
}

// The signed-in user and the active sheet. Signing in only takes a name; the name is sent with
// every request in the X-User header.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it. */
  readonly today = signal<string | null>(null);
  /** Whether retired people are listed: off when the screen opens, and left as it is by loading a sheet. */
  readonly showRetired = signal(false);
  /** Counts completed sheet loads, so the screen re-reads the sheet's data even for the same id. */
  readonly loaded = signal(0);
  /** Every value recorded of each dated setting of the active sheet (clerk-limit, floor, terms, terms-A, terms-B,
   *  terms-C, late-pct, cap), from-date first to last; null until the settings are read. */
  readonly dated = signal<Record<string, DatedValue[]> | null>(null);
  /** The active sheet's floor (two decimals) in force on its today: a live due is at least it; null until the settings are read. */
  readonly floor = computed(() => this.settingOn('floor', this.today()));
  /** The active sheet's terms in force on its today: a claim of a grade without its own is due by its date plus these many days; null until the settings are read. */
  readonly terms = computed(() => {
    const terms = this.settingOn('terms', this.today());
    return terms === null ? null : Number(terms);
  });
  /** The active sheet's late percent (two decimals) in force on its today: an overdue claim's due gains it of its figure every full 30 days. */
  readonly latePct = computed(() => this.settingOn('late-pct', this.today()));
  /** The active sheet's policy date (yyyy-mm-dd): a claim dated before it rounds half up, on or after it half to even;
   *  blank means the sheet's today; null until the settings are read. */
  readonly policyDate = signal<string | null>(null);
  /** The active sheet's cap (two decimals) in force on its today: a person's due-total is at most it; null when there
   *  is none or until the settings are read. */
  readonly cap = computed(() => this.settingOn('cap', this.today()));
  private loads = 0;

  signIn(name: string): void {
    this.user.set(name);
    this.sheet.set(null);
    this.today.set(null);
  }

  /**
   * The value of a dated setting in force on the date: the one with the latest from-date on or before it, else the
   * sheet's starting value; null when that is none, or until the settings are read.
   */
  settingOn(key: string, date: string | null): string | null {
    const dated = this.dated();
    if (dated === null || date === null) return null;
    let value: string | null = STARTING[key] ?? null;
    for (const d of dated[key] ?? []) {
      if (d.from <= date) value = d.value;
    }
    return value;
  }

  /** Request options carrying the signed-in user. */
  headers(): { headers: Record<string, string> } {
    return { headers: { 'X-User': this.user() ?? '' } };
  }

  /** Load a sheet by id; an id never used before starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const load = ++this.loads;
    const loaded = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    // A later load wins over a slower earlier one.
    if (load === this.loads) {
      this.show(loaded);
      this.loaded.update((n) => n + 1);
    }
  }

  /** Change the active sheet's today. */
  async setToday(today: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.put<SheetView>(
        `/api/sheets/${encodeURIComponent(id)}/today`,
        { today },
        { headers: { 'X-User': this.user() ?? '' } },
      ),
    );
    if (this.sheet() === saved.id) this.show(saved);
  }

  private show(view: SheetView): void {
    this.sheet.set(view.id);
    this.today.set(view.today);
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Period, periodOn } from '../periods/periods';
import { Rate, Rounding, dueOf, floored, percentOf, rateOn, sumDues } from '../rates/rates';

export interface Claim {
  id: number;
  personId: number;
  /** Two decimals, e.g. "2.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened; null for a DRAFT and once voided. */
  number: string | null;
  /** The due fixed when the claim was settled, two decimals; null when it has none and its due is live. */
  settledDue: string | null;
  /** The user who opened the claim; null for a DRAFT. That user cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows the due it bound it to. */
  stated: boolean;
  /** The due the last statement bound the claim to, two decimals; null when unbound, or bound with none (n/a). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person this claim corrects; null unless it is a correction. */
  corrects: string | null;
  /** The date (yyyy-mm-dd) that decides how its live figures round: its own, or a correction's corrected claim's. */
  roundingDate: string;
  /** Its place in its person's list: a claim with a later place is listed first (newest added, or last reassigned). */
  listed: number;
  /** The day (yyyy-mm-dd) the claim is due by, fixed when it was added from the terms of its person's grade on its date. */
  dueBy: string;
  /** Its status log, oldest first: one line per status it has had. */
  log: ClaimLogLine[];
  /** The date (yyyy-mm-dd) an OPEN claim is deferred until; null when it was never deferred. */
  deferredUntil: string | null;
}

/** A line of a claim's status log: the status, who changed it, the sheet's today then, and the due then (or n/a). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  /** yyyy-mm-dd */
  date: string;
  due: string;
}

/** Claims as listed: the latest list place first. */
export function byListed(a: Claim, b: Claim): number {
  return b.listed - a.listed || b.id - a.id;
}

/**
 * DRAFT when added, then OPEN, then SETTLED; a clerk settling above the clerk limit makes it PENDING until a steward
 * approves (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING claim may be VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Whether a claim is a correction (a negative amount): its due has no floor and no late charge. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
}

/**
 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
 * the sheet's today.
 */
export function counts(claim: Claim, today: string | null): boolean {
  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
}

/**
 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date. It then counts in no
 * total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export function deferred(claim: Claim, today: string | null): boolean {
  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/** Whether a claim is handled as open: OPEN or PENDING. It goes overdue, bears the late charge, and a hold takes it out. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether the claim's due follows its last statement now: a PENDING one shows its live figure while PENDING. */
export function bound(claim: Claim): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** One of a person's grades, from its from-date (yyyy-mm-dd); null from the beginning of time. */
export interface PersonGrade {
  grade: string;
  from: string | null;
}

/** The person's grade in force on the date: the one with the latest from-date on or before it. */
export function gradeOn(grades: PersonGrade[], date: string): string | undefined {
  let found: PersonGrade | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') <= (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/**
 * How the claim's live figures round: half up when its rounding date is before the sheet's policy date (the sheet's
 * today when blank), half to even on or after it.
 */
export function roundingOf(claim: Claim, session: Session): Rounding {
  const policy = session.policyDate() || session.today();
  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
}

/**
 * The due fixed when the claim was settled, else its figure (the one its person's last statement bound it to, else
 * its amount times the rate of its person's grade on its date, both in force on its date, raised to the sheet's floor on its date, or n/a with no rate) with its late
 * charge added on top. A correction has neither floor nor late charge.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const grade = gradeOn(grades, claim.date);
  const due = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date), roundingOf(claim, session));
  const figure = bound(claim)
    ? (claim.statedDue ?? 'n/a')
    : isCorrection(claim) ? due : floored(due, session.settingOn('floor', claim.date));
  return figure === 'n/a' ? figure : sumDues([figure, lateCharge(claim, figure, session)]);
}

/**
 * The late percent (the one in force on the claim's date) of the figure for every full 30 days an OPEN claim is past
 * its due-by on the sheet's today, rounded like the claim's due; 0.00 when it is not overdue, and on a correction.
 */
export function lateCharge(claim: Claim, figure: string, session: Session): string {
  const by = claim.dueBy;
  const today = session.today();
  const pct = session.settingOn('late-pct', claim.date);
  if (!isOpen(claim) || isCorrection(claim) || by === '' || today === null || pct === null) return '0.00';
  if (deferred(claim, today)) return '0.00';
  const days = Math.round((Date.parse(today) - Date.parse(by)) / 86_400_000);
  return days > 0 ? percentOf(figure, pct, Math.floor(days / 30), roundingOf(claim, session)) : '0.00';
}

/** Whether the claim's due is fixed, by settling or by a statement, rather than worked out from the rates. */
export function dueFixed(claim: Claim): boolean {
  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
}

/** Whether the claim is OPEN or PENDING, not deferred, and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string | null): boolean {
  return isOpen(claim) && today !== null && claim.dueBy < today && !deferred(claim, today);
}

type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';

/** Sums amounts with two decimals exactly, in whole cents. */
export function sumAmounts(amounts: string[]): string {
  const cents = amounts.reduce((total, a) => total + Math.round(Number(a) * 100), 0);
  return (cents / 100).toFixed(2);
}

// One person's claims, newest first, each with its due, and the form that adds a claim or, once a claim's editor is
