1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, computed, inject, input, output, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { Period, periodOn } from '../periods/periods';
6	import { Rate, Rounding, dueOf, floored, percentOf, rateOn, sumDues } from '../rates/rates';
7	
8	export interface Claim {
9	  id: number;
10	  personId: number;
11	  /** Two decimals, e.g. "2.50". */
12	  amount: string;
13	  /** yyyy-mm-dd */
14	  date: string;
15	  note: string;
16	  status: ClaimStatus;
17	  /** Given when the claim is opened; null for a DRAFT and once voided. */
18	  number: string | null;
19	  /** The due fixed when the claim was settled, two decimals; null when it has none and its due is live. */
20	  settledDue: string | null;
21	  /** The user who opened the claim; null for a DRAFT. That user cannot settle it. */
22	  openedBy: string | null;
23	  /** Whether the person's last statement bound the claim: it then shows the due it bound it to. */
24	  stated: boolean;
25	  /** The due the last statement bound the claim to, two decimals; null when unbound, or bound with none (n/a). */
26	  statedDue: string | null;
27	  /** The number of the SETTLED claim of the same person this claim corrects; null unless it is a correction. */
28	  corrects: string | null;
29	  /** The date (yyyy-mm-dd) that decides how its live figures round: its own, or a correction's corrected claim's. */
30	  roundingDate: string;
31	  /** Its place in its person's list: a claim with a later place is listed first (newest added, or last reassigned). */
32	  listed: number;
33	  /** The day (yyyy-mm-dd) the claim is due by, fixed when it was added from the terms of its person's grade on its date. */
34	  dueBy: string;
35	  /** Its status log, oldest first: one line per status it has had. */
36	  log: ClaimLogLine[];
37	  /** The date (yyyy-mm-dd) an OPEN claim is deferred until; null when it was never deferred. */
38	  deferredUntil: string | null;
39	}
40	
41	/** A line of a claim's status log: the status, who changed it, the sheet's today then, and the due then (or n/a). */
42	export interface ClaimLogLine {
43	  status: ClaimStatus;
44	  by: string;
45	  /** yyyy-mm-dd */
46	  date: string;
47	  due: string;
48	}
49	
50	/** Claims as listed: the latest list place first. */
51	export function byListed(a: Claim, b: Claim): number {
52	  return b.listed - a.listed || b.id - a.id;
53	}
54	
55	/**
56	 * DRAFT when added, then OPEN, then SETTLED; a clerk settling above the clerk limit makes it PENDING until a steward
57	 * approves (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING claim may be VOID.
58	 */
59	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
60	
61	/** Whether a claim is a correction (a negative amount): its due has no floor and no late charge. */
62	export function isCorrection(claim: Claim): boolean {
63	  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
64	}
65	
66	/**
67	 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
68	 * the sheet's today.
69	 */
70	export function counts(claim: Claim, today: string | null): boolean {
71	  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
72	}
73	
74	/**
75	 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date. It then counts in no
76	 * total, is not overdue, cannot be settled and is left unbound by a statement.
77	 */
78	export function deferred(claim: Claim, today: string | null): boolean {
79	  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
80	}
81	
82	/** Whether a claim is handled as open: OPEN or PENDING. It goes overdue, bears the late charge, and a hold takes it out. */
83	export function isOpen(claim: Claim): boolean {
84	  return claim.status === 'OPEN' || claim.status === 'PENDING';
85	}
86	
87	/** Whether the claim's due follows its last statement now: a PENDING one shows its live figure while PENDING. */
88	export function bound(claim: Claim): boolean {
89	  return claim.stated && claim.status !== 'PENDING';
90	}
91	
92	/** One of a person's grades, from its from-date (yyyy-mm-dd); null from the beginning of time. */
93	export interface PersonGrade {
94	  grade: string;
95	  from: string | null;
96	}
97	
98	/** The person's grade in force on the date: the one with the latest from-date on or before it. */
99	export function gradeOn(grades: PersonGrade[], date: string): string | undefined {
100	  let found: PersonGrade | undefined;
101	  for (const g of grades) {
102	    if (g.from !== null && g.from > date) continue;
103	    if (found === undefined || (found.from ?? '') <= (g.from ?? '')) found = g;
104	  }
105	  return found?.grade;
106	}
107	
108	/**
109	 * How the claim's live figures round: half up when its rounding date is before the sheet's policy date (the sheet's
110	 * today when blank), half to even on or after it.
111	 */
112	export function roundingOf(claim: Claim, session: Session): Rounding {
113	  const policy = session.policyDate() || session.today();
114	  return policy !== null && claim.roundingDate < policy ? 'half-up' : 'half-even';
115	}
116	
117	/**
118	 * The due fixed when the claim was settled, else its figure (the one its person's last statement bound it to, else
119	 * its amount times the rate of its person's grade on its date, both in force on its date, raised to the sheet's floor on its date, or n/a with no rate) with its late
120	 * charge added on top. A correction has neither floor nor late charge.
121	 */
122	export function claimDue(claim: Claim, rates: Rate[], grades: PersonGrade[], session: Session): string {
123	  if (claim.settledDue !== null) return claim.settledDue;
124	  const grade = gradeOn(grades, claim.date);
125	  const due = dueOf(claim.amount, grade === undefined ? undefined : rateOn(rates, grade, claim.date), roundingOf(claim, session));
126	  const figure = bound(claim)
127	    ? (claim.statedDue ?? 'n/a')
128	    : isCorrection(claim) ? due : floored(due, session.settingOn('floor', claim.date));
129	  return figure === 'n/a' ? figure : sumDues([figure, lateCharge(claim, figure, session)]);
130	}
131	
132	/**
133	 * The late percent (the one in force on the claim's date) of the figure for every full 30 days an OPEN claim is past
134	 * its due-by on the sheet's today, rounded like the claim's due; 0.00 when it is not overdue, and on a correction.
135	 */
136	export function lateCharge(claim: Claim, figure: string, session: Session): string {
137	  const by = claim.dueBy;
138	  const today = session.today();
139	  const pct = session.settingOn('late-pct', claim.date);
140	  if (!isOpen(claim) || isCorrection(claim) || by === '' || today === null || pct === null) return '0.00';
141	  if (deferred(claim, today)) return '0.00';
142	  const days = Math.round((Date.parse(today) - Date.parse(by)) / 86_400_000);
143	  return days > 0 ? percentOf(figure, pct, Math.floor(days / 30), roundingOf(claim, session)) : '0.00';
144	}
145	
146	/** Whether the claim's due is fixed, by settling or by a statement, rather than worked out from the rates. */
147	export function dueFixed(claim: Claim): boolean {
148	  return claim.settledDue !== null || (bound(claim) && claim.statedDue !== null);
149	}
150	
151	/** Whether the claim is OPEN or PENDING, not deferred, and its due-by is before the sheet's today. */
152	export function overdue(claim: Claim, today: string | null): boolean {
153	  return isOpen(claim) && today !== null && claim.dueBy < today && !deferred(claim, today);
154	}
155	
156	type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';
157	
158	/** Sums amounts with two decimals exactly, in whole cents. */
159	export function sumAmounts(amounts: string[]): string {
160	  const cents = amounts.reduce((total, a) => total + Math.round(Number(a) * 100), 0);
161	  return (cents / 100).toFixed(2);
162	}
163	
164	// One person's claims, newest first, each with its due, and the form that adds a claim or, once a claim's editor is
165	// opened, saves that claim. Rendered as a table cell inside the person's row.
166	@Component({
167	  selector: 'td[app-claims]',
168	  template: `
169	    <form (submit)="submit($event)">
170	      <label [for]="fieldId('amount')">Amount</label>
171	      <input
172	        [id]="fieldId('amount')"
173	        data-testid="claim-form-amount"
174	        inputmode="decimal"
175	        [value]="amount()"
176	        (input)="amount.set(value($event)); error.set(null)"
177	      />
178	      <label [for]="fieldId('date')">Date</label>
179	      <input
180	        [id]="fieldId('date')"
181	        type="date"
182	        data-testid="claim-form-date"
183	        [value]="date()"
184	        (input)="date.set(value($event)); error.set(null)"
185	      />
186	      <label [for]="fieldId('note')">Note</label>
187	      <input
188	        [id]="fieldId('note')"
189	        data-testid="claim-form-note"
190	        [value]="note()"
191	        (input)="note.set(value($event)); error.set(null)"
192	      />
193	      <label [for]="fieldId('corrects')">Corrects claim no.</label>
194	      <input
195	        [id]="fieldId('corrects')"
196	        data-testid="claim-form-corrects"
197	        [value]="corrects()"
198	        (input)="corrects.set(value($event)); error.set(null)"
199	      />
200	      <button type="submit" data-testid="claim-form-submit">
201	        {{ editing() === null ? 'Add claim' : 'Save claim' }}
202	      </button>
203	      @if (error(); as message) {
204	        <p role="alert" data-testid="claim-form-error">{{ message }}</p>
205	      }
206	    </form>
207	    @if (claims().length > 0) {
208	      <table>
209	        <caption class="visually-hidden">Claims of {{ personName() }}</caption>
210	        <thead>
211	          <tr>
212	            <th scope="col"><span class="visually-hidden">Select</span></th><th scope="col">No.</th><th scope="col">Amount</th><th scope="col">Date</th><th scope="col">Note</th><th scope="col">Due</th><th scope="col">Due by</th><th scope="col">Overdue</th>
213	            <th scope="col">Status</th><th scope="col">Opened by</th><th scope="col">Stated</th><th scope="col">Period</th><th scope="col">Corrects</th><th scope="col">Deferred</th><th scope="col">Deferred until</th><th scope="col">Log</th>
214	            <th scope="col"><span class="visually-hidden">Actions</span></th>
215	          </tr>
216	        </thead>
217	        <tbody>
218	          @for (c of claims(); track c.id) {
219	            <tr [attr.data-testid]="'claim-row-' + c.id">
220	              <td>
221	                <input
222	                  type="checkbox"
223	                  data-testid="claim-select"
224	                  [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date"
225	                  [checked]="selected().has(c.id)"
226	                  (change)="selectToggled.emit({ id: c.id, checked: checked($event) })"
227	                />
228	              </td>
229	              <td data-testid="claim-number">{{ c.number ?? '' }}</td>
230	              <td data-testid="claim-amount">{{ c.amount }}</td>
231	              <td data-testid="claim-date">{{ c.date }}</td>
232	              <td data-testid="claim-note">{{ c.note }}</td>
233	              <td data-testid="claim-due">{{ due(c) }}</td>
234	              <td data-testid="claim-due-by">{{ c.dueBy }}</td>
235	              <td data-testid="claim-overdue">{{ overdue(c) ? 'yes' : 'no' }}</td>
236	              <td data-testid="claim-status">{{ c.status }}</td>
237	              <td data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</td>
238	              <td data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</td>
239	              <td data-testid="claim-period">{{ periodOf(c) }}</td>
240	              <td data-testid="claim-corrects">{{ c.corrects ?? '' }}</td>
241	              <td data-testid="claim-deferred">{{ deferred(c) ? 'yes' : 'no' }}</td>
242	              <td data-testid="claim-deferred-until">{{ deferred(c) ? c.deferredUntil : '' }}</td>
243	              <td>
244	                <ol class="claim-log">
245	                  @for (line of c.log; track $index) {
246	                    <li data-testid="claim-log-line">{{ line.status }} by {{ line.by }} on {{ line.date }} due={{ line.due }}</li>
247	                  }
248	                </ol>
249	              </td>
250	              <td>
251	                <button
252	                  type="button"
253	                  data-testid="claim-edit"
254	                  [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
255	                  (click)="edit(c)"
256	                >
257	                  Edit
258	                </button>
259	                @if (editing() === c.id) {
260	                  <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
261	                }
262	                @for (a of actions; track a.action) {
263	                  <button
264	                    type="button"
265	                    [attr.data-testid]="'claim-' + a.action"
266	                    [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
267	                    (click)="act(c, a.action)"
268	                  >
269	                    {{ a.label }}
270	                  </button>
271	                }
272	                <label class="visually-hidden" [for]="'claim-defer-date-' + c.id">Defer until</label>
273	                <input
274	                  [id]="'claim-defer-date-' + c.id"
275	                  type="date"
276	                  data-testid="claim-defer-date"
277	                  [value]="deferDates()[c.id] ?? ''"
278	                  (input)="setDeferDate(c.id, value($event))"
279	                />
280	                <button
281	                  type="button"
282	                  data-testid="claim-defer"
283	                  [attr.aria-label]="'Defer claim of ' + c.amount + ' on ' + c.date"
284	                  (click)="defer(c)"
285	                >
286	                  Defer
287	                </button>
288	                <label class="visually-hidden" [for]="'claim-reassign-to-' + c.id">Reassign to</label>
289	                <select
290	                  [id]="'claim-reassign-to-' + c.id"
291	                  data-testid="claim-reassign-to"
292	                  (change)="setReassignTo(c.id, value($event))"
293	                >
294	                  <option value="" [selected]="!reassignTo()[c.id]">Reassign to…</option>
295	                  @for (o of others(); track o.id) {
296	                    <option [value]="o.id" [selected]="reassignTo()[c.id] === '' + o.id">{{ o.name }}</option>
297	                  }
298	                </select>
299	                <button
300	                  type="button"
301	                  data-testid="claim-reassign"
302	                  [attr.aria-label]="'Reassign claim of ' + c.amount + ' on ' + c.date"
303	                  (click)="reassign(c)"
304	                >
305	                  Reassign
306	                </button>
307	                <label class="visually-hidden" [for]="'claim-reject-reason-' + c.id">Reason to reject</label>
308	                <input
309	                  [id]="'claim-reject-reason-' + c.id"
310	                  data-testid="claim-reject-reason"
311	                  placeholder="Reason to reject"
312	                  [value]="rejectReasons()[c.id] ?? ''"
313	                  (input)="setRejectReason(c.id, value($event))"
314	                />
315	                @if (actionError(); as e) {
316	                  @if (e.id === c.id) {
317	                    <p role="alert" data-testid="claim-error">{{ e.message }}</p>
318	                  }
319	                }
320	              </td>
321	            </tr>
322	          }
323	        </tbody>
324	      </table>
325	    }
326	  `,
327	})
328	export class Claims {
329	  private readonly http = inject(HttpClient);
330	  private readonly session = inject(Session);
331	
332	  readonly personId = input.required<number>();
333	  readonly personName = input.required<string>();
334	  /** The person's claims, newest first. */
335	  readonly claims = input.required<Claim[]>();
336	  /** The person's grades, each from its from-date. */
337	  readonly grades = input.required<PersonGrade[]>();
338	  /** The sheet's rates: a claim's due uses the rate in force on the claim's date of the grade in force then. */
339	  readonly rates = input.required<Rate[]>();
340	  /** The sheet's periods: a claim belongs to the one whose dates contain its date. */
341	  readonly periods = input.required<Period[]>();
342	  /** The sheet's people, in the order they were added: a claim may be reassigned to any of the others. */
343	  readonly people = input<{ id: number; name: string }[]>([]);
344	  /** The date the person is retired from (yyyy-mm-dd); null while not retired. */
345	  readonly retiredFrom = input<string | null>(null);
346	  /** The ids of the sheet's claims selected to act on together. */
347	  readonly selected = input<ReadonlySet<number>>(new Set());
348	  /** A claim's checkbox was ticked or cleared. */
349	  readonly selectToggled = output<{ id: number; checked: boolean }>();
350	  /** A claim was added, saved or changed status. */
351	  readonly saved = output<Claim>();
352	
353	  protected readonly amount = signal('');
354	  protected readonly date = signal('');
355	  protected readonly note = signal('');
356	  /** The number of the settled claim a correction (a negative amount) corrects. */
357	  protected readonly corrects = signal('');
358	  /** The id of the claim whose editor is open, or null when the form adds a claim. */
359	  protected readonly editing = signal<number | null>(null);
360	  protected readonly error = signal<string | null>(null);
361	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
362	  private submitting = false;
363	  /** The error of the last status change refused, and the claim it belongs to. */
364	  protected readonly actionError = signal<{ id: number; message: string } | null>(null);
365	  protected readonly actions: { action: ClaimAction; label: string }[] = [
366	    { action: 'open', label: 'Open' },
367	    { action: 'settle', label: 'Settle' },
368	    { action: 'void', label: 'Void' },
369	    { action: 'approve', label: 'Approve' },
370	    { action: 'reject', label: 'Reject' },
371	    { action: 'resettle', label: 'Re-settle' },
372	  ];
373	  /** The people other than this one, whom a claim may be reassigned to. */
374	  protected readonly others = computed(() => this.people().filter((p) => p.id !== this.personId()));
375	  /** The id (as text) of the person picked to reassign each claim to, by claim id. */
376	  protected readonly reassignTo = signal<Record<number, string>>({});
377	  /** The reason typed to reject each PENDING claim, by claim id. */
378	  protected readonly rejectReasons = signal<Record<number, string>>({});
379	  /** The date (yyyy-mm-dd) picked to defer each OPEN claim until, by claim id. */
380	  protected readonly deferDates = signal<Record<number, string>>({});
381	
382	  protected fieldId(field: string): string {
383	    return `claim-form-${field}-${this.personId()}`;
384	  }
385	
386	  /** The due fixed when the claim was settled, else its amount times the rate on its date, or n/a with no rate. */
387	  protected due(claim: Claim): string {
388	    return claimDue(claim, this.rates(), this.grades(), this.session);
389	  }
390	
391	  /** Whether the claim is OPEN and was due by a day before the sheet's today. */
392	  protected overdue(claim: Claim): boolean {
393	    return overdue(claim, this.session.today());
394	  }
395	
396	  /** Whether the claim is deferred on the sheet's today. */
397	  protected deferred(claim: Claim): boolean {
398	    return deferred(claim, this.session.today());
399	  }
400	
401	  /** The name of the period the claim's date falls in, or blank when none. */
402	  protected periodOf(claim: Claim): string {
403	    return periodOn(this.periods(), claim.date)?.name ?? '';
404	  }
405	
406	  /** The closed period the date falls in, or undefined when none does. */
407	  private closedOn(date: string): Period | undefined {
408	    const period = periodOn(this.periods(), date);
409	    return period?.closed ? period : undefined;
410	  }
411	
412	  protected value(event: Event): string {
413	    return (event.target as HTMLInputElement).value;
414	  }
415	
416	  protected checked(event: Event): boolean {
417	    return (event.target as HTMLInputElement).checked;
418	  }
419	
420	  /** Open the claim's editor; only a DRAFT can be edited; to change an OPEN claim, void it and add a new one. */
421	  protected edit(claim: Claim): void {
422	    if (claim.status !== 'DRAFT') {
423	      this.reset();
424	      this.actionError.set({
425	        id: claim.id,
426	        message: `This claim is ${claim.status}: only a DRAFT can be edited. To change an open claim, void it and add a new one.`,
427	      });
428	      return;
429	    }
430	    this.editing.set(claim.id);
431	    this.amount.set(claim.amount);
432	    this.date.set(claim.date);
433	    this.note.set(claim.note);
434	    this.corrects.set(claim.corrects ?? '');
435	    this.error.set(null);
436	    this.actionError.set(null);
437	  }
438	
439	  protected reset(): void {
440	    this.editing.set(null);
441	    this.amount.set('');
442	    this.date.set('');
443	    this.note.set('');
444	    this.corrects.set('');
445	    this.error.set(null);
446	  }
447	
448	  protected setRejectReason(id: number, reason: string): void {
449	    this.rejectReasons.update((all) => ({ ...all, [id]: reason }));
450	    if (this.actionError()?.id === id) this.actionError.set(null);
451	  }
452	
453	  protected setDeferDate(id: number, date: string): void {
454	    this.deferDates.update((all) => ({ ...all, [id]: date }));
455	    if (this.actionError()?.id === id) this.actionError.set(null);
456	  }
457	
458	  /**
459	   * Defer an OPEN claim until the date picked for it; the store refuses a claim not OPEN, a date not after the sheet's
460	   * today, and a closed period.
461	   */
462	  protected async defer(claim: Claim): Promise<void> {
463	    this.actionError.set(null);
464	    const sheet = this.session.sheet();
465	    if (!sheet) return;
466	    const until = (this.deferDates()[claim.id] ?? '').trim();
467	    if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
468	      this.actionError.set({ id: claim.id, message: 'Pick the date to defer this claim until.' });
469	      return;
470	    }
471	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/defer`;
472	    try {
473	      const saved = await firstValueFrom(this.http.post<Claim>(url, { until }, this.session.headers()));
474	      this.setDeferDate(claim.id, '');
475	      if (this.session.sheet() === sheet) this.saved.emit(saved);
476	    } catch {
477	      const closed = this.closedOn(claim.date);
478	      const today = this.session.today();
479	      const message =
480	        claim.status !== 'OPEN'
481	          ? `This claim is ${claim.status}: only an OPEN claim can be deferred.`
482	          : closed
483	            ? `This claim is dated in the closed period ${closed.name}: it cannot be deferred.`
484	            : today !== null && until <= today
485	              ? `A claim can only be deferred to a date after today (${today}).`
486	              : 'This claim could not be deferred.';
487	      this.actionError.set({ id: claim.id, message });
488	    }
489	  }
490	
491	  protected setReassignTo(id: number, personId: string): void {
492	    this.reassignTo.update((all) => ({ ...all, [id]: personId }));
493	    if (this.actionError()?.id === id) this.actionError.set(null);
494	  }
495	
496	  /**
497	   * Move a DRAFT, OPEN or PENDING claim to the person picked for it; the store refuses a SETTLED or VOID claim, a
498	   * closed period, a person retired before its date, and a user who is not a steward.
499	   */
500	  protected async reassign(claim: Claim): Promise<void> {
501	    this.actionError.set(null);
502	    const sheet = this.session.sheet();
503	    if (!sheet) return;
504	    const to = this.others().find((p) => String(p.id) === this.reassignTo()[claim.id]);
505	    if (to === undefined) {
506	      this.actionError.set({ id: claim.id, message: 'Pick the person to reassign this claim to.' });
507	      return;
508	    }
509	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/reassign`;
510	    try {
511	      const saved = await firstValueFrom(this.http.post<Claim>(url, { personId: to.id }, this.session.headers()));
512	      this.setReassignTo(claim.id, '');
513	      if (this.session.sheet() === sheet) this.saved.emit(saved);
514	    } catch (e) {
515	      const closed = this.closedOn(claim.date);
516	      const message =
517	        e instanceof HttpErrorResponse && e.status === 403
518	          ? 'Only a steward can reassign a claim.'
519	          : closed
520	            ? `This claim is dated in the closed period ${closed.name}: it cannot be reassigned.`
521	            : claim.status === 'SETTLED' || claim.status === 'VOID'
522	              ? `This claim is ${claim.status}: only a DRAFT, OPEN or PENDING claim can be reassigned.`
523	              : `This claim could not be reassigned to ${to.name}.`;
524	      this.actionError.set({ id: claim.id, message });
525	    }
526	  }
527	
528	  /**
529	   * Open, settle, void, approve, reject or re-settle a claim; the store refuses a change its status, or the user's role, does not
530	   * allow. Rejecting takes the reason typed for the claim.
531	   */
532	  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
533	    this.actionError.set(null);
534	    const sheet = this.session.sheet();
535	    if (!sheet) return;
536	    const reason = (this.rejectReasons()[claim.id] ?? '').trim();
537	    if (action === 'reject' && reason === '') {
538	      this.actionError.set({ id: claim.id, message: 'Type a reason to reject this claim.' });
539	      return;
540	    }
541	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}`;
542	    try {
543	      const body = action === 'reject' ? { reason } : null;
544	      const saved = await firstValueFrom(this.http.post<Claim>(url, body, this.session.headers()));
545	      if (action === 'reject') this.setRejectReason(claim.id, '');
546	      if (this.session.sheet() === sheet) this.saved.emit(saved);
547	    } catch (e) {
548	      const closed = this.closedOn(claim.date);
549	      const message =
550	        e instanceof HttpErrorResponse && e.status === 403
551	          ? action === 'settle'
552	            ? 'Whoever opened this claim cannot also settle it: another user must settle it.'
553	            : action === 'resettle'
554	            ? 'Only a steward can re-settle a claim.'
555	            : 'Only a steward can approve or reject a pending claim, and not the one who opened it.'
556	          : closed
557	              ? `This claim is dated in the closed period ${closed.name}: it cannot be ${pastOf[action]}.`
558	              : action === 'settle' && this.deferred(claim)
559	                ? `This claim is deferred until ${claim.deferredUntil}: it cannot be settled before then.`
560	              : action === 'resettle'
561	                ? `This claim is ${claim.status}: only a SETTLED claim can be re-settled.`
562	                : `This claim's status does not let it be ${pastOf[action]}.`;
563	      this.actionError.set({ id: claim.id, message });
564	    }
565	  }
566	
567	  protected async submit(event: Event): Promise<void> {
568	    event.preventDefault();
569	    if (this.submitting) return;
570	    this.error.set(null);
571	    const sheet = this.session.sheet();
572	    if (!sheet) return;
573	    const amount = this.amount().trim();
574	    if (!/^-?\d+(\.\d{1,2})?$/.test(amount)) {
575	      this.error.set('Type an amount with at most two decimals; a negative one is a correction.');
576	      return;
577	    }
578	    const corrects = this.corrects().trim();
579	    if (corrects.length > 255) {
580	      this.error.set('Type the number of the settled claim the correction corrects.');
581	      return;
582	    }
583	    const date = this.date().trim();
584	    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
585	      this.error.set('Pick a date for the claim, or leave it blank for today.');
586	      return;
587	    }
588	    const body = { amount, date: date || null, note: this.note(), corrects: corrects || null };
589	    const editing = this.editing();
590	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
591	    this.submitting = true;
592	    try {
593	      const saved = await firstValueFrom(
594	        editing === null
595	          ? this.http.post<Claim>(`${base}/people/${this.personId()}/claims`, body, this.session.headers())
596	          : this.http.put<Claim>(`${base}/claims/${editing}`, body, this.session.headers()),
597	      );
598	      if (this.session.sheet() === sheet) {
599	        this.reset();
600	        this.saved.emit(saved);
601	      }
602	    } catch (e) {
603	      const dated = date || (this.session.today() ?? '');
604	      const closed = this.closedOn(dated);
605	      const retiredFrom = this.retiredFrom();
606	      const why = closed
607	        ? ` Its date is in the closed period ${closed.name}.`
608	        : retiredFrom !== null && dated > retiredFrom
609	          ? ` ${this.personName()} is retired from ${retiredFrom}.`
610	          : editing !== null && e instanceof HttpErrorResponse && e.status === 409
611	          ? ' Only a DRAFT claim can be edited.'
612	          : e instanceof HttpErrorResponse && e.status === 422
613	          ? ' A negative amount is a correction: it must name, by number, a settled claim of this person.'
614	          : '';
615	      this.error.set((editing === null ? 'The claim could not be added.' : 'The claim could not be saved.') + why);
616	    } finally {
617	      this.submitting = false;
618	    }
619	  }
620	}
621	
622	const pastOf: Record<ClaimAction, string> = {
623	  open: 'opened',
624	  settle: 'settled',
625	  void: 'voided',
626	  approve: 'approved',
627	  reject: 'rejected',
628	  resettle: 're-settled',
629	};
630

